#include "shared_ring.h"
#include <cassert>
int main(){lux::SharedRing r;r.generation=17;r.outputGeneration=2;for(int i=0;i<3;++i){auto& s=r.slots[i];s.frame=i+1;assert(lux::transition(s,lux::Free,lux::Writing));assert(lux::transition(s,lux::Writing,lux::Ready));assert(lux::transition(s,lux::Ready,lux::Reading));}for(auto& s:r.slots)assert(!lux::transition(s,lux::Free,lux::Writing));lux::FrameKey k{17,2,2,1};assert(lux::retire(r,k));assert(lux::transition(r.slots[1],lux::Free,lux::Writing));r.slots[1].frame=4;assert(!lux::retire(r,k));assert(!lux::transition(r.slots[1],lux::Ready,lux::Reading));assert(lux::transition(r.slots[1],lux::Writing,lux::Ready));assert(lux::transition(r.slots[1],lux::Ready,lux::Reading));k.frame=4;k.outputGeneration=1;assert(!lux::retire(r,k));k.outputGeneration=2;assert(lux::retire(r,k));}
